SELECT 'target' AS evidence, clock_timestamp() AS observed_at, current_database() AS database, inet_server_addr()::text AS host, inet_server_port() AS port, version() AS server_version, pg_is_in_recovery() AS in_recovery, current_setting('default_transaction_read_only') AS default_read_only, current_setting('transaction_read_only') AS diagnostic_transaction_read_only, has_database_privilege(current_database(),'CONNECT') AS can_connect, has_schema_privilege('public','CREATE') AS can_create_in_public, has_table_privilege('public."__EFMigrationsHistory"','INSERT') AS can_insert_history, has_table_privilege('public."ShippingWebhookLogs"','INSERT,UPDATE,DELETE') AS can_write_inbox
SELECT 'claims_presence' AS evidence, to_regclass('public."ShippingWebhookClaims"')::text AS claims_table
SELECT 'migration_history' AS evidence, "MigrationId", "ProductVersion" FROM "__EFMigrationsHistory" ORDER BY "MigrationId"
SELECT 'relevant_schema' AS evidence, table_name, column_name, data_type FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('ShippingWebhookLogs','OutboxMessage','OutboxState','InboxState','LedgerJournalLines','PaymentSettlementOrders','PaymentSettlementBatches') ORDER BY table_name, ordinal_position
SELECT 'inbox_indexes' AS evidence, indexname, indexdef FROM pg_indexes WHERE schemaname='public' AND tablename='ShippingWebhookLogs' ORDER BY indexname
SELECT 'sessions' AS evidence, pid, application_name, client_addr::text, client_port, backend_start, state, wait_event_type, wait_event, query_start, CASE WHEN query ~ 'OutboxMessage|OutboxState' THEN 'EF bus outbox table access' WHEN query ~ 'ShippingWebhook' THEN 'shipping inbox/claim access' ELSE 'other (query text withheld)' END AS query_class FROM pg_stat_activity WHERE datname=current_database() ORDER BY pid
SELECT 'table_activity' AS evidence, relname, n_tup_ins, n_tup_upd, n_tup_del, n_live_tup FROM pg_stat_user_tables WHERE relname IN ('OutboxMessage','OutboxState','InboxState','ShippingWebhookLogs','Orders','Shipments','Tenants') ORDER BY relname
SELECT 'outbox_messages' AS evidence, "SequenceNumber", "MessageId", "OutboxId", "InboxMessageId", "InboxConsumerId", md5(to_jsonb(m)::text) AS row_hash FROM "OutboxMessage" m ORDER BY "SequenceNumber"
SELECT 'outbox_states' AS evidence, "OutboxId", md5(to_jsonb(s)::text) AS row_hash FROM "OutboxState" s ORDER BY "OutboxId"
SELECT 'inbox_states' AS evidence, "Id", "MessageId", "ConsumerId", md5(to_jsonb(i)::text) AS row_hash FROM "InboxState" i ORDER BY "Id"
SELECT 'shipping_inbox' AS evidence, "Id", md5(to_jsonb(l)::text) AS row_hash FROM "ShippingWebhookLogs" l ORDER BY "Id"
SELECT 'orders' AS evidence, "Id", "TenantId", md5(to_jsonb(o)::text) AS row_hash FROM "Orders" o ORDER BY "Id"
SELECT 'shipments' AS evidence, "Id", "TenantId", "OrderId", md5(to_jsonb(s)::text) AS row_hash FROM "Shipments" s ORDER BY "Id"
SELECT 'tenants' AS evidence, "Id", md5(to_jsonb(t)::text) AS row_hash FROM "Tenants" t ORDER BY "Id"
SELECT 'baseline_counts' AS evidence, (SELECT count(*) FROM "OutboxMessage") AS bus_messages, (SELECT count(*) FROM "OutboxState") AS bus_states, (SELECT count(*) FROM "InboxState") AS bus_inbox, (SELECT count(*) FROM "ShippingWebhookLogs") AS webhook_inbox, (SELECT count(*) FROM "Orders") AS orders, (SELECT count(*) FROM "Shipments") AS shipments, (SELECT count(*) FROM "Tenants") AS tenants
SELECT 'qa_cod_order' AS evidence, "Id", "Status", "PaymentStatus", "FinancialPostingStatus", md5(to_jsonb(o)::text) AS row_hash FROM "Orders" o WHERE "Id"='62a692f0-3393-467b-9f43-46a7a7ecae9e'
SELECT 'qa_cod_journals' AS evidence, "Id", md5(to_jsonb(j)::text) AS row_hash FROM "LedgerJournalEntries" j WHERE "SourceId"='62a692f0-3393-467b-9f43-46a7a7ecae9e' ORDER BY "Id"
SELECT 'qa_cod_settlement_membership' AS evidence, md5(to_jsonb(s)::text) AS row_hash FROM "PaymentSettlementOrders" s WHERE "OrderId"='62a692f0-3393-467b-9f43-46a7a7ecae9e' ORDER BY md5(to_jsonb(s)::text)
SELECT 'qa_cod_settlement_batches' AS evidence, b."Id", md5(to_jsonb(b)::text) AS row_hash FROM "PaymentSettlementBatches" b WHERE EXISTS (SELECT 1 FROM "PaymentSettlementOrders" s WHERE s."SettlementBatchId"=b."Id" AND s."TenantId"=b."TenantId" AND s."OrderId"='62a692f0-3393-467b-9f43-46a7a7ecae9e') ORDER BY b."Id"
SELECT 'qa_cod_accounting_outbox' AS evidence, "Id", md5(to_jsonb(a)::text) AS row_hash FROM "AccountingOutboxMessages" a WHERE "BusinessEntityId"='62a692f0-3393-467b-9f43-46a7a7ecae9e' ORDER BY "Id"
